import http from 'http';
type Fn = (...a: any[]) => any;
function wrap(fn: Fn): any { return function (...a: any[]) { return fn(...a); }; }
async function main(): Promise<void> {
  const s0 = http.createServer((req, res) => { res.end(); });
  const s = s0.listen(0, '127.0.0.1', wrap(() => {
    console.log('L', s.address().port > 0, s0.address().port > 0);
    s.close();
  }));
  await new Promise<void>((r) => setTimeout(r, 300));
}
